    Arrays.sort(nums);
    int ans = nums[0] + nums[1] + nums[nums.length - 1];
    for (int i = 0; i < nums.length - 2; i++) {
      int left = i + 1, right = nums.length - 1;
      while (left < right) {
        int sum = nums[i] + nums[left] + nums[right];
        if (Math.abs(target - ans) > Math.abs(target - sum)) {
          ans = sum;
        }
        if (sum < target) {
          left++;
        } else {
          right--;
        }
      }
    }
    return ans;
  }
}

class Solution:
    def threeSumClosest(self, nums: List[int], target: int) -> int:
        nums.sort()
        ans = nums[0] + nums[1] + nums[-1]
        for i in range(len(nums) - 2):
            left, right = i + 1, len(nums) - 1
            while left < right:
                total = nums[i] + nums[left] + nums[right]
                if abs(target - ans) > abs(target - total):
                    ans = total
                if total < target:
                    left += 1
                else:
                    right -= 1
        return ans

impl Solution {
  pub fn three_sum_closest(mut nums: Vec<i32>, target: i32) -> i32 {
    nums.sort();
    let n = nums.len();
    let mut ans = nums[0] + nums[1] + nums[n - 1];
    for i in 0..n - 2 {
      let (mut left, mut right) = (i + 1, n - 1);
      while left < right {
        let sum = nums[i] + nums[left] + nums[right];
        if (target - ans).abs() > (target - sum).abs() {
          ans = sum;
        }
        if sum < target {
          left += 1;
        } else {
          right -= 1;
        }
      }
    }
    ans
  }
}

const threeSumClosest = (nums: number[], target: number): number => {
  nums.sort((a, b) => a - b);
  let ans = nums[0] + nums[1] + nums[nums.length - 1];

  for (let i = 0; i < nums.length - 2; i++) {
    let left = i + 1;
    let right = nums.length - 1;
    while (left < right) {
      const sum = nums[i] + nums[left] + nums[right];
      if (Math.abs(target - ans) > Math.abs(target - sum)) {
        ans = sum;
      }
      if (sum < target) left++;
      else right--;
    }
  }

  return ans;
};
